// Extrait guildId / channelId / messageId depuis un lien de message Discord
// Format attendu : https://discord.com/channels/<serveur>/<salon>/<message>
const url = String($input.first().json.lienMessage || '').trim();
const m = url.match(/channels\/(\d+|@me)\/(\d+)\/(\d+)/);
if (!m) {
  throw new Error("Lien Discord invalide : " + url + "\nAttendu : https://discord.com/channels/<serveur>/<salon>/<message> (clic droit sur le message -> Copier le lien du message)");
}
return [{ json: { lienMessage: url, guildId: m[1], channelId: m[2], messageId: m[3] } }];

// Lit le texte du message de concours et en déduit lot / valeur / date limite / accroche.
// Tout champ rempli à la main dans "Paramètres du tirage" a la priorité sur ce qui est déduit.
const params = $('Paramètres du tirage').first().json;
const msg = $input.first().json;

const brut = String(msg.content || '').replace(/\*\*/g, '').replace(/__/g, '');
const lignes = brut.split('\n').map((l) => l.trim()).filter(Boolean);
// enlève les emojis / puces en tête de ligne
const sansPuce = (s) => s.replace(/^[^\p{L}\p{N}«"(]+/u, '').trim();

// --- Lot : la ligne "🔥 iKier 70W à gagner !"
let lot = '';
const idxLot = lignes.findIndex((l) => /à gagner/i.test(l));
if (idxLot >= 0) {
  lot = sansPuce(lignes[idxLot]).replace(/\s*(à|a)\s+gagner\s*!*\s*$/i, '').trim();
}

// --- Valeur : "💰 Valeur indicative" puis "Environ 1 599 €"
let valeur = '';
const idxVal = lignes.findIndex((l) => /valeur/i.test(l));
if (idxVal >= 0) {
  const zone = [lignes[idxVal], lignes[idxVal + 1] || ''].join(' ');
  const m = zone.match(/(\d[\d\s\u00a0\u202f.,]*)\s*(€|EUR\b|euros?)/i);
  if (m) {
    const nombre = m[1].replace(/[\s\u00a0\u202f]+/g, ' ').trim();
    valeur = (/environ|indicative|~/i.test(zone) ? '≈ ' : '') + nombre + ' €';
  }
}

// --- Date limite : "jusqu'au dimanche 5 juillet inclus"
let dateLimite = '';
const mDate = brut.match(/(?:jusqu['\u2019]?\s*(?:au|\u00e0)|avant\s+le)\s+(?:le\s+)?([^\n,.;!?]{3,45}?)\s*(?:inclus|compris|minuit|\u00e0\s+\d|pour\s|$)/i);
if (mDate) dateLimite = mDate[1].trim();

// --- Accroche : 1re phrase descriptive après la ligne du lot
const ignore = /(réagir|participer|participation|tirage au sort|valeur indicative|bonne chance|serveur|comment)/i;
const depart = idxLot >= 0 ? idxLot + 1 : 0;
let accroche =
  lignes.slice(depart).find((l) => l.length >= 60 && !ignore.test(l)) ||
  lignes.find((l) => l.length >= 60 && !ignore.test(l)) ||
  '';
if (accroche.length > 210) {
  const coupe = accroche.slice(0, 210);
  accroche = coupe.slice(0, Math.max(coupe.lastIndexOf('. '), coupe.lastIndexOf(' '))).trim() + '…';
}
if (!accroche) {
  accroche = "Toutes les personnes ayant réagi au message sont dans la roue. Un seul nom s'arrête dans la fenêtre.";
}

const choisi = (manuel, auto) => (String(manuel || '').trim() ? String(manuel).trim() : auto);

const concours = {
  lot: choisi(params.lot, lot),
  valeur: choisi(params.valeur, valeur),
  dateLimite: choisi(params.dateLimite, dateLimite),
  accroche: choisi(params.accroche, accroche),
};

console.log('Détails du concours : ' + JSON.stringify(concours));

// on laisse passer le message tel quel (les réactions servent au nœud suivant)
return [{ json: { ...msg, concours } }];

// Une ligne par (émoji x type de réaction) présent sur le message.
// type 0 = réaction normale, type 1 = super-réaction (burst) : l'API les renvoie séparément.
const ids = $('Extraire les IDs').first().json;
const msg = $input.first().json;
const reactions = msg.reactions || [];

if (!reactions.length) {
  throw new Error("Aucune réaction sur ce message (ou le bot ne voit pas le salon : il lui faut Voir le salon + Voir l'historique des messages).");
}

const out = [];
for (const r of reactions) {
  const e = r.emoji || {};
  // émoji custom -> "nom:id" ; émoji unicode -> le caractère lui-même
  const key = e.id ? `${e.name}:${e.id}` : e.name;
  const label = e.id ? `:${e.name}:` : e.name;
  const normal = (r.count_details && r.count_details.normal != null) ? r.count_details.normal : (r.count || 0);
  const burst = (r.count_details && r.count_details.burst) || 0;
  const base = {
    guildId: ids.guildId,
    channelId: ids.channelId,
    messageId: ids.messageId,
    emojiKey: key,
    emojiParam: encodeURIComponent(key),
    emojiLabel: label,
    emojiId: e.id || null,
  };
  if (normal > 0) out.push({ json: { ...base, type: 0, typeLabel: 'normale', attendus: normal } });
  if (burst > 0) out.push({ json: { ...base, type: 1, typeLabel: 'super', attendus: burst } });
}
return out;

// Rattache chaque utilisateur reçu à l'émoji de l'itération en cours.
// $runIndex = numéro de passage dans la boucle (batchSize = 1 -> 1 émoji par passage).
const liste = $('Lister les émojis').all();
const ctx = (liste[$runIndex] || $('Boucle émoji').first()).json;

const users = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j) continue;
  if (Array.isArray(j)) users.push(...j);
  else if (Array.isArray(j.data)) users.push(...j.data);
  else if (j.id) users.push(j);
}

// Ne jamais renvoyer 0 item : sinon la boucle s'arrête avant la fin.
if (!users.length) {
  return [{ json: { _vide: true, emojiLabel: ctx.emojiLabel, typeLabel: ctx.typeLabel } }];
}

return users.map((u) => ({
  json: {
    userId: u.id,
    username: u.username,
    globalName: u.global_name || '',
    bot: !!u.bot,
    emojiLabel: ctx.emojiLabel,
    emojiKey: ctx.emojiKey,
    typeLabel: ctx.typeLabel,
  },
}));

// Fusionne toutes les itérations de la boucle et dédoublonne par ID Discord.
// -> 1 item = 1 personne, quel que soit le nombre d'émojis avec lesquels elle a réagi.
const parUser = new Map();

for (const item of $input.all()) {
  const j = item.json;
  if (!j || j._vide || !j.userId) continue;
  if (!parUser.has(j.userId)) {
    parUser.set(j.userId, {
      userId: j.userId,
      pseudo: j.username,
      nomAffiche: j.globalName || j.username,
      bot: j.bot,
      emojis: new Set(),
    });
  }
  const label = j.typeLabel === 'super' ? `${j.emojiLabel} (super)` : j.emojiLabel;
  parUser.get(j.userId).emojis.add(label);
}

const lignes = [...parUser.values()]
  .map((u) => ({
    userId: u.userId,
    pseudo: u.pseudo,
    nomAffiche: u.nomAffiche,
    bot: u.bot,
    nbReactions: u.emojis.size,
    reactions: [...u.emojis].join(' '),
  }))
  .sort((a, b) => String(a.nomAffiche).localeCompare(String(b.nomAffiche), 'fr'));

if (!lignes.length) {
  throw new Error("Aucun utilisateur récupéré : vérifie que le bot a bien accès au salon et que le message porte des réactions.");
}

console.log(`${lignes.length} personne(s) unique(s) ayant réagi`);
return lignes.map((json) => ({ json }));

