<script>
/* Données injectées par n8n depuis les réactions Discord ------------------- */
const participants = __PARTICIPANTS_JSON__;
const WINNER_IDX = __WINNER_IDX__;   // index tiré au sort côté n8n (crypto.getRandomValues)
const WINNER = participants[WINNER_IDX];
/* ------------------------------------------------------------------------- */

const N = participants.length;
const ITEM_H = 100;        // px, matches .reel-item height
const LOOPS = 6;           // full passes before settling

const track = document.getElementById("track");
const btn = document.getElementById("spin");
const reelGlow = document.getElementById("reelGlow");
const winnerBox = document.getElementById("winner");
const winnerName = document.getElementById("winnerName");

// Build a long strip: several full loops + final landing on the winner,
// centered in the window (with one item above + below visible).
const totalItems = LOOPS * N + WINNER_IDX + 1; // +1 so winner lands at center
const strip = [];
for(let i=0;i<totalItems+2;i++){              // +2 padding for top/bottom visible rows
  strip.push(participants[i % N]);
}
strip.forEach(name=>{
  const d=document.createElement("div");
  d.className="reel-item";
  d.textContent=name;
  track.appendChild(d);
});

// viewport shows 3 rows (300px). Center row is the selection window.
// To center item at index \`k\`, translateY so that item k sits in the middle row.
// middle row top offset = ITEM_H (the 2nd visible row).
function offsetForIndex(k){ return -(k*ITEM_H - ITEM_H); }

// start position: show first items
let startIndex = 1;                    // so row 0 is the top padding
track.style.transform = "translateY(" + offsetForIndex(startIndex) + "px)";

let spun=false;
function easeOutQuint(t){return 1-Math.pow(1-t,5);}

let currentY = offsetForIndex(startIndex);
function highlightCenter(){
  const items=track.children;
  const centerIdx=Math.round((-currentY+ITEM_H)/ITEM_H);
  for(let i=0;i<items.length;i++){
    items[i].classList.toggle("center", i===centerIdx);
  }
}

btn.addEventListener("click",()=>{
  if(spun) return;
  spun=true; btn.disabled=true;
  reelGlow.classList.add("on");

  const targetIndex = totalItems - 1;          // winner's position in the strip
  const fromY = offsetForIndex(startIndex);
  const toY = offsetForIndex(targetIndex);
  const dur = 6200;
  const startT = performance.now();

  function frame(now){
    const t = Math.min(1,(now-startT)/dur);
    const e = easeOutQuint(t);
    currentY = fromY + (toY-fromY)*e;
    track.style.transform = "translateY(" + currentY + "px)";
    highlightCenter();
    if(t<1){requestAnimationFrame(frame);}
    else{
      currentY = toY;
      track.style.transform = "translateY(" + toY + "px)";
      highlightCenter();
      winnerName.textContent = WINNER;
      winnerBox.classList.add("show");
      reelGlow.classList.add("on");
      burst();
    }
  }
  requestAnimationFrame(frame);
});

highlightCenter();

/* ---- confetti ---- */
const cv=document.getElementById("fx"), ctx=cv.getContext("2d");
function size(){cv.width=innerWidth;cv.height=innerHeight;}
size();addEventListener("resize",size);
let parts=[],anim=null;
const colors=["#F2435C","#ff7286","#e9c87a","#ffffff","#f7f5f1"];
function burst(){
  parts=[];
  for(let i=0;i<170;i++){
    parts.push({x:innerWidth/2,y:innerHeight*0.42,
      vx:(Math.random()-.5)*14,vy:Math.random()*-15-4,
      g:.32+Math.random()*.12,s:5+Math.random()*7,
      rot:Math.random()*Math.PI,vr:(Math.random()-.5)*.3,
      c:colors[Math.floor(Math.random()*colors.length)],life:1});
  }
  if(!anim) tick();
}
function tick(){
  ctx.clearRect(0,0,cv.width,cv.height);
  let alive=false;
  parts.forEach(p=>{
    p.vy+=p.g;p.x+=p.vx;p.y+=p.vy;p.vx*=.99;p.rot+=p.vr;p.life-=.004;
    if(p.y<innerHeight+40 && p.life>0) alive=true;
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);
    ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.c;
    ctx.fillRect(-p.s/2,-p.s/2,p.s,p.s*0.6);ctx.restore();
  });
  if(alive){anim=requestAnimationFrame(tick);}else{anim=null;ctx.clearRect(0,0,cv.width,cv.height);}
}
</script>
</body>
</html>
`;

const concours = $('Lire les détails du concours').first().json.concours || {};

const participants = $input.all()
  .map((i) => i.json)
  .filter((u) => u && u.userId && !u.bot); // les bots ne participent pas

if (!participants.length) {
  throw new Error("Aucun participant : personne n'a réagi (hors bots).");
}

// Tirage : crypto.getRandomValues + rejet des valeurs hors plage => aucun biais modulo.
function indexAleatoire(n) {
  try {
    if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
      const limite = Math.floor(4294967296 / n) * n;
      const buf = new Uint32Array(1);
      let x;
      do { crypto.getRandomValues(buf); x = buf[0]; } while (x >= limite);
      return x % n;
    }
  } catch (e) { /* repli ci-dessous */ }
  return Math.floor(Math.random() * n);
}

const idx = indexAleatoire(participants.length);
const gagnant = participants[idx];
const noms = participants.map((u) => u.nomAffiche || u.pseudo);

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const dateFr = $now.setZone('Europe/Paris').toFormat('dd/LL/yyyy');

// --- bandeau de chips : seules les infos réellement trouvées sont affichées
const chips = [`      <span class="chip"><span class="dot"></span> <b>${noms.length}</b> participants</span>`];
if (concours.lot) chips.push(`      <span class="chip">🎁 <b>${esc(concours.lot)}</b></span>`);
if (concours.valeur) chips.push(`      <span class="chip">Valeur <b>${esc(concours.valeur)}</b></span>`);
chips.push(concours.dateLimite
  ? `      <span class="chip">Clôturé le ${esc(concours.dateLimite)}</span>`
  : `      <span class="chip">Tirage du ${esc(dateFr)}</span>`);

const listeHtml = noms
  .map((n, i) => `      <li><span class="num">${String(i + 1).padStart(2, '0')}</span>${esc(n)}</li>`)
  .join('\n');

const titre = concours.lot
  ? `Tirage au sort · ${concours.lot} — La Nouvelle École`
  : 'Tirage au sort · La Nouvelle École';
const nomFichier = `tirage-${(concours.lot || 'concours').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40)}-${$now.setZone('Europe/Paris').toFormat('yyyy-LL-dd')}.html`;

const html = TEMPLATE
  .replaceAll('__PARTICIPANTS_JSON__', JSON.stringify(noms).replace(/</g, '\\u003c'))
  .replaceAll('__WINNER_IDX__', String(idx))
  .replaceAll('__COUNT__', String(noms.length))
  .replaceAll('__DATE__', esc(dateFr))
  .replaceAll('__TITRE__', esc(titre))
  .replaceAll('__ACCROCHE__', esc(concours.accroche || ''))
  .replaceAll('__CHIPS_HTML__', chips.join('\n'))
  .replaceAll('__LISTE_HTML__', listeHtml);

// Message tout prêt pour annoncer le résultat sur Discord
const annonce = [
  '🏆 Le tirage au sort est terminé !',
  '',
  concours.lot
    ? `Merci à toutes et tous d'avoir participé au concours ${concours.lot} 🎁`
    : "Merci à toutes et tous d'avoir participé 🎁",
  `${noms.length} personnes étaient dans la roue, une seule pouvait gagner.`,
  '',
  `🎉 Félicitations à ${gagnant.nomAffiche} !`,
  '',
  'Contacte-nous en message privé pour organiser la remise du lot.',
  'Et pas d\'inquiétude pour les autres : d\'autres concours arrivent très vite sur le serveur 💪',
].join('\n');

console.log(`Gagnant tiré au sort : ${gagnant.nomAffiche} (${gagnant.userId}) parmi ${noms.length} participants`);

return [{
  json: {
    gagnant: gagnant.nomAffiche,
    gagnantPseudo: gagnant.pseudo,
    gagnantId: gagnant.userId,
    nbParticipants: noms.length,
    participants: noms,
    concours,
    dateTirage: dateFr,
    annonceGagnant: annonce,
    fichier: nomFichier,
    htmlBase64: Buffer.from(html, 'utf8').toString('base64'),
    html,
  },
}];

// Assemble l'annonce Discord : l'IA n'écrit que la partie descriptive,
// la structure (participation, date, tirage) est garantie ici.
const details = $('Détails du concours').first().json;

// --- récupération du texte du modèle, quelle que soit la forme de la réponse
function texteModele(j) {
  if (!j) return '';
  if (typeof j === 'string') return j;
  if (Array.isArray(j.output)) {
    for (const bloc of j.output) {
      const c = Array.isArray(bloc.content) ? bloc.content.find((x) => x && (x.text || x.type === 'output_text')) : null;
      if (c && c.text) return c.text;
    }
  }
  return j.output_text || j.text || (j.message && j.message.content) || j.content || '';
}

let bloc = {};
const brut = String(texteModele($input.first().json) || '').trim()
  .replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
try {
  bloc = JSON.parse(brut);
} catch (e) {
  // repli : on reconstruit une annonce correcte même si le modèle n'a pas renvoyé du JSON
  bloc = {
    titre: `🔥 ${details.nomLot} à gagner !`,
    intro: 'On vous propose un nouveau lot à gagner sur le serveur :',
    paragraphes: brut ? [brut] : [String(details.infosLot || '')],
  };
}

const titre = String(bloc.titre || `🔥 ${details.nomLot} à gagner !`).trim();
const intro = String(bloc.intro || 'On vous propose un nouveau lot à gagner sur le serveur :').trim();
const paragraphes = (Array.isArray(bloc.paragraphes) ? bloc.paragraphes : [String(bloc.paragraphes || '')])
  .map((p) => String(p).trim())
  .filter(Boolean);

const valeur = String(details.valeurLot || '').trim();
const dateLimite = String(details.dateLimite || '').trim();

function assembler(paras) {
  const blocs = [
    '🎁 Un nouveau concours sur le serveur !',
    intro,
    titre,
    paras.join('\n\n'),
  ];
  if (valeur) blocs.push(`💰 Valeur indicative\n${/^(environ|≈|~)/i.test(valeur) ? valeur : 'Environ ' + valeur}`);
  blocs.push("⏳ Comment participer ?\nC'est très simple : il vous suffit de réagir à ce message pour valider votre participation.");
  if (dateLimite) blocs.push(`Vous avez jusqu'au ${dateLimite} inclus pour tenter votre chance.`);
  blocs.push('🏆 Tirage au sort\nLe gagnant sera tiré au sort à la fin du concours et annoncé directement ici, sur Discord.');
  blocs.push('Bonne chance à tous, et merci de continuer à faire vivre la communauté 🎉');
  return blocs.filter(Boolean).join('\n\n');
}

// Discord : 2000 caractères maximum. On retire des paragraphes descriptifs si besoin.
let paras = paragraphes.slice();
let annonce = assembler(paras);
while (annonce.length > 2000 && paras.length > 1) {
  paras = paras.slice(0, -1);
  annonce = assembler(paras);
}
if (annonce.length > 2000) annonce = annonce.slice(0, 1997) + '…';

return [{
  json: {
    lot: details.nomLot,
    valeur,
    dateLimite,
    longueur: annonce.length,
    limiteDiscordOk: annonce.length <= 2000,
    paragraphesRetires: paragraphes.length - paras.length,
    annonce,
  },
}];
